#[test]
fn session_lock_repeated_already_constructed_failures_do_not_grow_output_registry() {
    let mut harness = KeybindingHarness::new(true);
    for attempt in 0..3 {
        while harness.renderer_events.try_recv().is_ok() {}
        let (mut client, globals) = connect_secondary_client(&mut harness);
        let (compositor_name, compositor_version) = globals["wl_compositor"];
        let (output_name, output_version) = globals["wl_output"];
        let (manager_name, manager_version) = globals["ext_session_lock_manager_v1"];
        bind_global(
            &mut client,
            compositor_name,
            "wl_compositor",
            compositor_version.min(5),
            4,
        );
        bind_global(
            &mut client,
            output_name,
            "wl_output",
            output_version.min(4),
            5,
        );
        bind_global(
            &mut client,
            manager_name,
            "ext_session_lock_manager_v1",
            manager_version.min(1),
            6,
        );
        send_display_request(&mut client, 0, 7);
        harness.dispatch_client();
        let _ = events_until_callback(&mut client, 7);
        send_request(&mut client, 6, 1, &words(&[8]));
        send_request(&mut client, 4, 0, &words(&[9]));
        send_request(&mut client, 9, 6, &[]);
        send_request(&mut client, 8, 1, &words(&[10, 9, 5]));
        harness.dispatch_client();
        let (offending, code, message) = read_protocol_error(&mut client);
        assert_eq!(offending, 8, "unexpected protocol error: {message}");
        assert_eq!(
            code,
            SessionLockError::AlreadyConstructed as u32,
            "unexpected protocol error: {message}"
        );
        assert_eq!(
            harness
                .server
                .state
                .session_lock_state
                .locked_output_count(),
            0,
            "failing construction {attempt} left an output registered"
        );
        drop(client);
        pump_protocol_event_loop_until(
            &mut harness.server,
            "failed lock client disconnect abort",
            |state| matches!(state.lock_lifecycle, LockLifecycle::Unlocked),
        );
    }
}

#[test]
fn session_lock_acked_buffer_maps_in_lock_band_above_overlay() {
    let mut harness = KeybindingHarness::new(true);
    send_request(
        &mut harness.client,
        TEST_TOPLEVEL_ID,
        2,
        &wire_string_argument("Private title"),
    );
    send_request(
        &mut harness.client,
        TEST_TOPLEVEL_ID,
        3,
        &wire_string_argument("org.cosmix.Private"),
    );
    map_initial_test_toplevel(&mut harness);
    #[cfg(feature = "bus")]
    let ordinary_id = test_toplevel_record(&harness).id.0;
    #[cfg(feature = "bus")]
    {
        let before = port_snapshot::snapshot(&harness.server.state, &snapshot_context("nested"))
            .expect("pre-lock snapshot");
        let ordinary = before
            .surfaces
            .get(&format!("s{ordinary_id}"))
            .expect("ordinary toplevel projected before lock");
        assert!(ordinary.visible);
        assert_eq!(ordinary.title.as_deref(), Some("Private title"));
        assert_eq!(ordinary.app_id.as_deref(), Some("org.cosmix.Private"));
        assert!(before.windows.contains_key(&format!("s{ordinary_id}")));
        assert_eq!(before.focus.session_lock, "none");
    }
    let (overlay, _) = map_test_layer_surface(
        &mut harness,
        0,
        TestLayerSpec {
            layer: WlrLayer::Overlay as u32,
            ..TestLayerSpec::default()
        },
    );
    let lock = begin_test_session_lock(&mut harness);
    #[cfg(feature = "bus")]
    {
        let locking = port_snapshot::snapshot(&harness.server.state, &snapshot_context("nested"))
            .expect("locking snapshot");
        let ordinary = locking
            .surfaces
            .get(&format!("s{ordinary_id}"))
            .expect("ordinary toplevel shape remains projected");
        assert!(!ordinary.visible);
        assert_eq!(ordinary.title, None);
        assert_eq!(ordinary.app_id, None);
        assert!(locking.windows.is_empty());
        assert_eq!(locking.focus.session_lock, "locking");
    }
    ack_and_map_test_lock_surface(&mut harness, lock);
    let lock_record = test_lock_record(&harness, lock.surface);
    assert!(lock_record.mapped);
    assert_eq!(lock_record.layout.z.band, StackBand::Lock);
    assert!(
        test_layer_record(&harness, overlay.surface).layout.z < lock_record.layout.z,
        "lock band sorts above Overlay"
    );
    #[cfg(feature = "bus")]
    {
        let snapshot = port_snapshot::snapshot(&harness.server.state, &snapshot_context("nested"))
            .expect("fixture coordinates are exactly representable");
        let lock = snapshot
            .surfaces
            .values()
            .find(|surface| surface.role == "lock")
            .expect("lock role projected");
        assert!(lock.mapped);
        assert!(lock.visible);
        assert_eq!(lock.band, "lock");
        assert!(lock.output.is_some());
        assert_eq!(snapshot.stack.first(), Some(&lock.id));
        assert!(lock.layer.is_none());
        assert!(snapshot.windows.is_empty());
        assert_eq!(snapshot.focus.session_lock, "locking");
    }
    let _ = present_test_security_epoch(&mut harness, lock.lock);
    #[cfg(feature = "bus")]
    {
        let locked = port_snapshot::snapshot(&harness.server.state, &snapshot_context("nested"))
            .expect("locked snapshot");
        assert!(locked.windows.is_empty());
        assert_eq!(locked.focus.session_lock, "locked");
    }
    let _ = unlock_test_session(&mut harness, lock);
    #[cfg(feature = "bus")]
    {
        let after = port_snapshot::snapshot(&harness.server.state, &snapshot_context("nested"))
            .expect("post-unlock snapshot");
        let ordinary = after
            .surfaces
            .get(&format!("s{ordinary_id}"))
            .expect("ordinary toplevel projected after unlock");
        assert!(ordinary.visible);
        assert_eq!(ordinary.title.as_deref(), Some("Private title"));
        assert_eq!(ordinary.app_id.as_deref(), Some("org.cosmix.Private"));
        assert!(after.windows.contains_key(&format!("s{ordinary_id}")));
        assert_eq!(after.focus.session_lock, "none");
    }
}

